import{_ as o,l as i,o as e,c as n,v as r,p as l,x as t,d,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"闪存对照","description":"","frontmatter":{"title":"闪存对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/flash-memory.md","filePath":"cs/flash-memory.md","lastUpdated":1789023840000}'),E={name:"cs/flash-memory.md"};function p(c,a,m,D,R,_){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="闪存对照" tabindex="-1">闪存对照 <a class="header-anchor" href="#闪存对照" aria-label="Permalink to &quot;闪存对照&quot;">​</a></h1><div class="epigraph"><p>DRAM 靠电容、掉电即忘；闪存把电荷关进浮栅，不刷新也能留，但写是按块擦再编程，不能当随机存取的主存。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/dram-refresh">DRAM 刷新</a>钉死了易失阵列的周期性读回写。本课不重推保留时间，也不从文件系统 FTL 另起。缺口是对照：<strong>非易失</strong>如何进组成课——能当 BIOS/盘，不能替换那套需刷新的主存时序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浮栅（或电荷陷阱）存 0/1，读近似随机；写前通常要擦除，擦除粒度是块，远大于字。编程电压高、次数有限（磨损）。缺口不是半导体工艺步骤，而是与 SRAM/DRAM 的角色划分：片上 SRAM 快且易失，DRAM 主存要刷新，闪存作外存或片上 ROM 替代，接口是命令队列而不是「地址一到数据就稳」。</p><p>NOR 可按字节读、便于原地执行；NAND 密度高、按页读，作 SSD。本课点到，不把通道、磨损均衡写成 OS 课。</p><h3 id="闪存不是「不需要刷新的-dram」" tabindex="-1">闪存不是「不需要刷新的 DRAM」 <a class="header-anchor" href="#闪存不是「不需要刷新的-dram」" aria-label="Permalink to &quot;闪存不是「不需要刷新的 DRAM」&quot;">​</a></h3><p>随机写延迟与寿命模型完全不同。把闪存插进单周期数据存储器框，关键路径与磨损都会说错。掉电保存不等于可以当寄存器。</p><p><span class="marginnote">Harris 把非易失列为另一类存储器。Patterson/Hennessy 用磁盘/闪存当存储层次底层。控制器常有独立时钟，<a href="/cs/clock-domain">下一课</a>的跨域从这里开始有实物。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：选字线，阈值电压判决。写：先擦块再编程页。CPU 经控制器发命令，完成以中断或轮询通知——中断入口很后才讲，本课只承认「多拍、另一时钟」。</p>',11)),(e(),l(h,null,{default:t(()=>[A(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRAM%5B%22SRAM%EF%BC%9A%E9%9D%99%E6%80%81%E3%80%81%E8%B4%B5%22%5D%20--%3E%20DRAM%5B%22DRAM%EF%BC%9A%E5%AF%86%E3%80%81%E8%A6%81%E5%88%B7%E6%96%B0%22%5D%0A%20%20DRAM%20--%3E%20FLASH%5B%22%E9%97%AA%E5%AD%98%EF%BC%9A%E9%9D%9E%E6%98%93%E5%A4%B1%E3%80%81%E5%9D%97%E6%93%A6%22%5D%0A%20%20FLASH%20--%3E%20ROLE%5B%22%E5%A4%96%E5%AD%98%20%2F%20%E4%BB%A3%E7%A0%81%20ROM%22%5D%0A%20%20ROLE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%97%B6%E9%92%9F%E5%9F%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>存储程序的指令可以放在 NOR 闪上直接取指（片上 MCU），或先拷到 SRAM/DRAM。后课冯·诺依曼图里的「存储器」教学上仍是 DRAM/SRAM；闪存在层次最底下。刷新义务没有了，换成磨损与擦除。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 3D NAND 层数、不把光刻产线请进来。不讨论文件系统日志。EEPROM 字节可改是同一非易失家族的小容量形态。</p><p>后课默认：主存仍是 DRAM（加刷新）；闪存是非易失外存或 ROM；其控制器时钟可与 CPU 无关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闪存非易失，写按块擦、有磨损。</li><li>不能当 DRAM 的免刷新版主存。</li><li>控制器可能独立于 CPU 时钟，交给时钟域课。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const M=o(E,[["render",p]]);export{u as __pageData,M as default};
